mapper.select:
select * from (
    select

        (IFNULL(day_plan_qty, 0) + IFNULL(night_plan_qty, 0)) as daily_total_qty,
        b.MONTH_PLAN_QTY as month_plan,
        CEILING(b.MONTH_REMAIN_QTY) as month_plan_os,
        d.COLOR_TYPE,
        d.COLOR_CODE
    from t_xwyy_assist_schedule a
    LEFT JOIN (
        select MATERIAL_CODE,MONTH_PLAN_QTY,MONTH_REMAIN_QTY
        from T_XWYY_MONTH_PLAN_SURPLUS
        where YEAR=#{year,jdbcType=VARCHAR}
        and MONTH= #{month,jdbcType=VARCHAR}
        and del_flag = '0'
    ) b on a.BIG_ROLL_CODE=b.MATERIAL_CODE
    LEFT JOIN T_XWYY_BIG_ROLL_COLOR d ON a.BIG_ROLL_CODE = d.BIG_ROLL_CODE AND d.del_Flag = '0' and d.status='0'
    where a.del_flag = '0'
    and a.schedule_date = #{scheduleDate}

        and INSTR(a.big_roll_code, #{bigRollCode,jdbcType=VARCHAR}) > 0


        and INSTR(a.original_line_code, #{originalLineCode,jdbcType=VARCHAR}) > 0

    and a.production_status = #{productionStatus}
    and instr(concat(',',a.machine_id,','),  concat(',',#{machineId},','))>0
    and a.IS_RELEASE = #{isRelease}
    order by (case when instr(machine_id,',') > 0 then machine_id when machine_id is null or machine_id = '' then '0' else '-1' end) desc/*多个机台 和 没有机台的排在前面*/,a.CREATE_TIME
) t

    order by ${orderStr}
